package co.com.empresa.infrastructure.config.kafka;import org.apache.kafka.clients.consumer.ConsumerConfig;import org.apache.kafka.common.serialization.StringDeserializer;import org.junit.jupiter.api.BeforeEach;import org.junit.jupiter.api.DisplayName;import org.junit.jupiter.api.Test;import org.springframework.boot.kafka.autoconfigure.KafkaProperties;import org.springframework.kafka.core.DefaultKafkaConsumerFactory;import org.springframework.kafka.support.serializer.ErrorHandlingDeserializer;import org.springframework.kafka.support.serializer.JacksonJsonDeserializer;import java.util.Map;import static org.junit.jupiter.api.Assertions.assertEquals;class KafkaConsumerConfigTest {    private KafkaProperties kafkaProperties;    private KafkaConfig kafkaConfig;    @BeforeEach    void setUp() {        kafkaProperties = new KafkaProperties();        kafkaConfig = new KafkaConfig(kafkaProperties);    }    @Test    @DisplayName("consumerFactory: Should configure key deserializer as StringDeserializer")    void consumerFactory_ConfiguresKeyDeserializer() {        DefaultKafkaConsumerFactory<String, Object> factory = (DefaultKafkaConsumerFactory<String, Object>) kafkaConfig.consumerFactory();        Map<String, Object> configs = factory.getConfigurationProperties();        assertEquals(StringDeserializer.class, configs.get(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG),                "Key deserializer should be StringDeserializer");    }    @Test    @DisplayName("consumerFactory: Should configure ErrorHandlingDeserializer for value")    void consumerFactory_ConfiguresErrorHandlingDeserializer() {        DefaultKafkaConsumerFactory<String, Object> factory = (DefaultKafkaConsumerFactory<String, Object>) kafkaConfig.consumerFactory();        Map<String, Object> configs = factory.getConfigurationProperties();        assertEquals(ErrorHandlingDeserializer.class, configs.get(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG),                "Value deserializer should be ErrorHandlingDeserializer");    }    @Test    @DisplayName("consumerFactory: Should configure JSON trusted packages")    void consumerFactory_ConfiguresTrustedPackages() {        DefaultKafkaConsumerFactory<String, Object> factory = (DefaultKafkaConsumerFactory<String, Object>) kafkaConfig.consumerFactory();        Map<String, Object> configs = factory.getConfigurationProperties();        assertEquals("*", configs.get("spring.json.trusted.packages"),                "JSON trusted packages should be '*'");    }    @Test    @DisplayName("consumerFactory: Should configure JacksonJsonDeserializer for error handling")    void consumerFactory_ConfiguresJsonDeserializerForErrorHandling() {        DefaultKafkaConsumerFactory<String, Object> factory = (DefaultKafkaConsumerFactory<String, Object>) kafkaConfig.consumerFactory();        Map<String, Object> configs = factory.getConfigurationProperties();        assertEquals(JacksonJsonDeserializer.class.getName(),                configs.get(ErrorHandlingDeserializer.VALUE_DESERIALIZER_CLASS),                "Error handling deserializer should be JacksonJsonDeserializer");    }}